export const LAB_LINK_EXACT_REGEX = /^Link:LabOrder:([1-9][0-9]*)$/;
const LAB_LINK_INLINE_REGEX = /\s*Link:LabOrder:([1-9][0-9]*)\s*/g;

/**
 * Extracts the LabOrder ID when `notes` is strictly an internal singleton
 * `Link:LabOrder:<id>` linkage token generated by the backend.
 *
 * @param {string|null|undefined} notes
 * @returns {string|null}
 */
export function extractLabLinkOrderId(notes) {
    if (typeof notes !== 'string') return null;
    const match = LAB_LINK_EXACT_REGEX.exec(notes.trim());
    return match ? match[1] : null;
}

/**
 * Returns true if `notes` represents an internal `Link:LabOrder:<id>` marker.
 *
 * @param {string|null|undefined} notes
 * @returns {boolean}
 */
export function isInternalLabLinkNote(notes) {
    return extractLabLinkOrderId(notes) !== null;
}

/**
 * Formats treatment notes for human display without ever exposing raw
 * `Link:LabOrder:<id>` tokens, while keeping DB values untouched.
 *
 * @param {string|null|undefined} notes
 * @param {(key: string, defaultValue?: string, options?: Object) => string} [t]
 * @returns {string}
 */
export function formatTreatmentNotesForDisplay(notes, t) {
    if (typeof notes !== 'string') return '';
    const trimmed = notes.trim();
    if (!trimmed) return '';

    const exactOrderId = extractLabLinkOrderId(trimmed);
    if (exactOrderId) {
        if (typeof t === 'function') {
            const translated = t(
                'patientDetails.treatment_history.linked_lab_order_badge',
                'مرتبط بطلب معمل #{{id}}',
                { id: exactOrderId },
            );
            return String(translated).replaceAll('{{id}}', exactOrderId);
        }
        return `مرتبط بطلب معمل #${exactOrderId}`;
    }

    if (!trimmed.includes('Link:LabOrder:')) {
        return notes;
    }

    return trimmed.replace(LAB_LINK_INLINE_REGEX, ' ').trim();
}
